mapper.select:
SELECT s.id, s.warehouse_id, w.warehouse_name, s.product_id, p.product_code, p.product_name, p.spec, p.unit, s.quantity, p.min_stock, p.max_stock, p.cost_price, (SELECT SUM(s2.quantity) FROM stock s2 WHERE s2.product_id = s.product_id AND s2.deleted = 0) AS total_stock FROM stock s LEFT JOIN warehouse w ON w.id = s.warehouse_id AND w.deleted = 0 LEFT JOIN product p ON p.id = s.product_id AND p.deleted = 0 WHERE s.deleted = 0
AND s.warehouse_id = #{warehouseId}
AND s.product_id = #{productId}
AND p.product_name LIKE CONCAT('%', #{productName}, '%')
AND p.product_code LIKE CONCAT('%', #{productCode}, '%')
ORDER BY s.update_time DESC

SELECT s.id, s.warehouse_id, w.warehouse_name, s.product_id, p.product_code, p.product_name, p.spec, p.unit, s.quantity, p.min_stock, p.max_stock, p.cost_price, CASE WHEN p.min_stock IS NOT NULL AND p.min_stock > 0 AND s.quantity < p.min_stock THEN 1 WHEN p.max_stock IS NOT NULL AND p.max_stock > 0 AND s.quantity > p.max_stock THEN 2 ELSE NULL END AS warning_type, (SELECT SUM(s2.quantity) FROM stock s2 WHERE s2.product_id = s.product_id AND s2.deleted = 0) AS total_stock FROM stock s LEFT JOIN warehouse w ON w.id = s.warehouse_id AND w.deleted = 0 LEFT JOIN product p ON p.id = s.product_id AND p.deleted = 0 WHERE s.deleted = 0 AND ( (p.min_stock IS NOT NULL AND p.min_stock > 0 AND s.quantity < p.min_stock) OR (p.max_stock IS NOT NULL AND p.max_stock > 0 AND s.quantity > p.max_stock) )
AND s.warehouse_id = #{warehouseId}
ORDER BY CASE WHEN p.min_stock IS NOT NULL AND p.min_stock > 0 AND s.quantity < p.min_stock THEN 0 ELSE 1 END, s.warehouse_id

SELECT t.order_type, t.order_type_label, t.order_no, t.warehouse_id, t.warehouse_name, t.product_id, t.product_code, t.product_name, t.spec, t.unit, t.quantity, t.direction, t.related_warehouse_name, t.remark, t.audit_time, t.create_time FROM (
SELECT 'PO' AS order_type, '采购入库' AS order_type_label, po.order_no, po.warehouse_id, w.warehouse_name, pod.product_id, pod.product_code, pod.product_name, pod.spec, pod.unit, pod.quantity AS quantity, 'IN' AS direction, NULL AS related_warehouse_name, pod.remark, po.audit_time, po.create_time FROM purchase_order po INNER JOIN purchase_order_detail pod ON pod.order_id = po.id LEFT JOIN warehouse w ON w.id = po.warehouse_id AND w.deleted = 0 WHERE po.deleted = 0 AND po.audit_status = 1 AND pod.product_id = #{productId}
UNION ALL
SELECT 'PR' AS order_type, '采购退货' AS order_type_label, pr.order_no, pr.warehouse_id, w.warehouse_name, prd.product_id, prd.product_code, prd.product_name, prd.spec, prd.unit, -prd.quantity AS quantity, 'OUT' AS direction, NULL AS related_warehouse_name, prd.remark, pr.audit_time, pr.create_time FROM purchase_return_order pr INNER JOIN purchase_return_order_detail prd ON prd.order_id = pr.id LEFT JOIN warehouse w ON w.id = pr.warehouse_id AND w.deleted = 0 WHERE pr.deleted = 0 AND pr.audit_status = 1 AND prd.product_id = #{productId}
UNION ALL
SELECT 'SO' AS order_type, '销售出库' AS order_type_label, so.order_no, so.warehouse_id, w.warehouse_name, sod.product_id, sod.product_code, sod.product_name, sod.spec, sod.unit, -sod.quantity AS quantity, 'OUT' AS direction, NULL AS related_warehouse_name, sod.remark, so.audit_time, so.create_time FROM sale_order so INNER JOIN sale_order_detail sod ON sod.order_id = so.id LEFT JOIN warehouse w ON w.id = so.warehouse_id AND w.deleted = 0 WHERE so.deleted = 0 AND so.audit_status = 1 AND sod.product_id = #{productId}
UNION ALL
SELECT 'SR' AS order_type, '销售退货' AS order_type_label, sr.order_no, sr.warehouse_id, w.warehouse_name, srd.product_id, srd.product_code, srd.product_name, srd.spec, srd.unit, srd.quantity AS quantity, 'IN' AS direction, NULL AS related_warehouse_name, srd.remark, sr.audit_time, sr.create_time FROM sale_return_order sr INNER JOIN sale_return_order_detail srd ON srd.order_id = sr.id LEFT JOIN warehouse w ON w.id = sr.warehouse_id AND w.deleted = 0 WHERE sr.deleted = 0 AND sr.audit_status = 1 AND srd.product_id = #{productId}
UNION ALL
SELECT 'TO' AS order_type, '调拨出库' AS order_type_label, st.order_no, st.from_warehouse_id AS warehouse_id, wf.warehouse_name, std.product_id, std.product_code, std.product_name, std.spec, std.unit, -std.quantity AS quantity, 'OUT' AS direction, wt.warehouse_name AS related_warehouse_name, std.remark, st.audit_time, st.create_time FROM stock_transfer st INNER JOIN stock_transfer_detail std ON std.order_id = st.id LEFT JOIN warehouse wf ON wf.id = st.from_warehouse_id AND wf.deleted = 0 LEFT JOIN warehouse wt ON wt.id = st.to_warehouse_id AND wt.deleted = 0 WHERE st.deleted = 0 AND st.audit_status = 1 AND std.product_id = #{productId}
UNION ALL
SELECT 'TR' AS order_type, '调拨入库' AS order_type_label, st.order_no, st.to_warehouse_id AS warehouse_id, wt.warehouse_name, std.product_id, std.product_code, std.product_name, std.spec, std.unit, std.quantity AS quantity, 'IN' AS direction, wf.warehouse_name AS related_warehouse_name, std.remark, st.audit_time, st.create_time FROM stock_transfer st INNER JOIN stock_transfer_detail std ON std.order_id = st.id LEFT JOIN warehouse wf ON wf.id = st.from_warehouse_id AND wf.deleted = 0 LEFT JOIN warehouse wt ON wt.id = st.to_warehouse_id AND wt.deleted = 0 WHERE st.deleted = 0 AND st.audit_status = 1 AND std.product_id = #{productId}
UNION ALL
SELECT 'PY' AS order_type, '盘盈入库' AS order_type_label, sc.profit_order_no AS order_no, sc.warehouse_id, w.warehouse_name, scd.product_id, scd.product_code, scd.product_name, scd.spec, scd.unit, scd.difference AS quantity, 'IN' AS direction, NULL AS related_warehouse_name, scd.remark, sc.audit_time, sc.create_time FROM stock_check sc INNER JOIN stock_check_detail scd ON scd.order_id = sc.id LEFT JOIN warehouse w ON w.id = sc.warehouse_id AND w.deleted = 0 WHERE sc.deleted = 0 AND sc.audit_status = 1 AND scd.difference > 0 AND scd.product_id = #{productId}
UNION ALL
SELECT 'PL' AS order_type, '盘亏出库' AS order_type_label, sc.loss_order_no AS order_no, sc.warehouse_id, w.warehouse_name, scd.product_id, scd.product_code, scd.product_name, scd.spec, scd.unit, scd.difference AS quantity, 'OUT' AS direction, NULL AS related_warehouse_name, scd.remark, sc.audit_time, sc.create_time FROM stock_check sc INNER JOIN stock_check_detail scd ON scd.order_id = sc.id LEFT JOIN warehouse w ON w.id = sc.warehouse_id AND w.deleted = 0 WHERE sc.deleted = 0 AND sc.audit_status = 1 AND scd.difference < 0 AND scd.product_id = #{productId} ) t ORDER BY t.audit_time DESC
